function createBasePresenceChanged(): PresenceChanged {
  return { peer: new Uint8Array(0), online: false };
}

export const PresenceChanged: MessageFns<PresenceChanged> = {
  encode(message: PresenceChanged, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.peer.length !== 0) {
      writer.uint32(10).bytes(message.peer);
    }
    if (message.online !== false) {
      writer.uint32(16).bool(message.online);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): PresenceChanged {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBasePresenceChanged();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.peer = reader.bytes();
          continue;
        }
        case 2: {
          if (tag !== 16) {
            break;
          }

          message.online = reader.bool();
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): PresenceChanged {
    return {
      peer: isSet(object.peer) ? bytesFromBase64(object.peer) : new Uint8Array(0),
      online: isSet(object.online) ? globalThis.Boolean(object.online) : false,
    };
  },

  toJSON(message: PresenceChanged): unknown {
    const obj: any = {};
    if (message.peer.length !== 0) {
      obj.peer = base64FromBytes(message.peer);
    }
    if (message.online !== false) {
      obj.online = message.online;
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<PresenceChanged>, I>>(base?: I): PresenceChanged {
    return PresenceChanged.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<PresenceChanged>, I>>(object: I): PresenceChanged {
    const message = createBasePresenceChanged();
    message.peer = object.peer ?? new Uint8Array(0);
    message.online = object.online ?? false;
    return message;
  },
};

